class Swatch {
  constructor(r, g, b, a){
    this.r = sig(r)
    this.g = sig(g)
    this.b = sig(b)
    this.a = sig(a)

    this.color = mem(() => [
      this.r(),
      this.g(),
      this.b(),
      this.a()
    ])
  }

  update(r, g, b, a){
    this.color = [r, g, b, a]
  }

  toString(){
    return "rgba("+this.color().join(",")+ ");"
  }

  render() {
    let that = this
    let background = mem(() => 
      "background: " + mem(that.toString.bind(that))()
      + "width: 400px;"
      + "height: 400px;" )

    console.log(background())

    return () => html`.swatch [style=${background}]`
  }
}

