async function post(url = "", body, headers) {
  try {
    let f = await fetch(url, {
      method: "POST",
      headers: {"Content-Type": "application/json",
                ...headers
               },
      body: JSON.stringify(body)
    }).then((res) => res.json())
    return f
  } catch {
    return null
  }
}

